function district(s=playerActor.state){return s.x<-370?'Ocean Drive':s.x>225?'Skyline District':s.z<-300?'North Quarter':s.z>300?'Palm Quarter':'Downtown';}
function formatTime(t){return `${Math.floor(t/60).toString().padStart(2,'0')}:${(t%60).toFixed(2).padStart(5,'0')}`;}
function syncMenu(){if(!playerActor)return;$('#session-distance').innerHTML=`${(distance/1000).toFixed(2)} <small>KM</small>`;$('#session-speed').innerHTML=`${Math.round(playerActor.state.speed*3.6)} <small>KM/H</small>`;$('#district').textContent=district().toUpperCase();$('#resume').innerHTML=`${firstDrive?'Take the wheel':'Keep driving'} <span>↗</span>`;$('#menu-status').textContent=raceActive?`COASTAL SPRINT · CHECKPOINT ${checkpoint+1} / ${gates.length}`:'A LITTLE FURTHER. A LITTLE FREER.';$('#race').textContent=raceActive?'Cancel sprint ↗':'Start coastal sprint ↗';if(raceActive)$('#race-status').textContent=`${formatTime(raceTime)} · Checkpoint ${checkpoint+1} of ${gates.length}`;else if(best)$('#race-status').textContent=`Coastal sprint best · ${formatTime(best)}`;drawMap();}
function setPause(value){if(!ready)return;paused=value;keys.clear();$('#menu').hidden=!value;$('#pause').hidden=value;$('#touch').hidden=value||!touchEnabled;if(value)syncMenu();else firstDrive=false;writeTelemetry();if(audioCtx)audioCtx[value?'suspend':'resume']();}
