const map=$('#minimap'),ctx=map.getContext('2d');function drawMap(){ctx.fillStyle='#173a38';ctx.fillRect(0,0,map.width,map.height);const scale=.175,ox=map.width/2,oy=map.height/2;ctx.save();ctx.translate(ox,oy);ctx.scale(scale,scale);ctx.fillStyle='#334b40';ctx.fillRect(WORLD.left,WORLD.top,WORLD.right-WORLD.left,WORLD.bottom-WORLD.top);ctx.fillStyle='#829184';for(const x of WORLD.roadsX)ctx.fillRect(x-11,WORLD.top,22,1340);for(const z of WORLD.roadsZ)ctx.fillRect(WORLD.left,z-11,980,22);ctx.fillStyle='#b8c5a9';for(const c of traffic){const s=c.actor.state;ctx.fillRect(s.x-3,s.z-3,6,6);}if(raceActive){ctx.fillStyle='#def79e';ctx.beginPath();ctx.arc(...gates[checkpoint],18,0,Math.PI*2);ctx.fill();}const s=playerActor.state;ctx.translate(s.x,s.z);ctx.rotate(-s.heading);ctx.fillStyle='#def79e';ctx.beginPath();ctx.moveTo(0,-34);ctx.lineTo(22,23);ctx.lineTo(0,10);ctx.lineTo(-22,23);ctx.closePath();ctx.fill();ctx.restore();}
