function updateTransforms(dt){const s=playerActor.state;pos.set(s.x,0,s.z);forward.set(-Math.sin(s.heading),0,-Math.cos(s.heading));player.position.copy(pos);player.rotation.y=s.heading;visual.rotation.z=lerp(visual.rotation.z,-s.yawRate*s.forwardSpeed*.0012,1-Math.exp(-dt*6));if(currentRide){currentRide.group.visible=camMode!==2;wheelDistance+=s.forwardSpeed*dt;for(const w of currentRide.wheels){wheelQuat.setFromAxisAngle(wheelAxis,wheelDistance/.4142);w.node.quaternion.copy(w.base).multiply(wheelQuat);if(w.front){steerQuat.setFromAxisAngle(steerAxis,steer*playerActor.config.steerAngle/(1+Math.abs(s.forwardSpeed)/24));w.node.quaternion.premultiply(steerQuat);}}}for(const c of traffic){const st=c.actor.state;c.mesh.position.set(st.x,0,st.z);c.mesh.rotation.y=st.heading;}sun.position.set(s.x-140,130,s.z-130);sun.target.position.set(s.x,0,s.z);sun.target.updateMatrixWorld();}
